import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import crypto from "crypto";

export async function GET(req: NextRequest) {
  try {
    const { searchParams } = new URL(req.url);
    const code = searchParams.get("code");

    if (!code) {
      return NextResponse.json({ error: "Missing tracking code" }, { status: 400 });
    }

    const trackingLink = await prisma.trackingLink.findUnique({
      where: { code },
    });

    if (!trackingLink) {
      return NextResponse.json({ error: "Invalid tracking code" }, { status: 404 });
    }

    const ip = req.headers.get("x-forwarded-for") ?? req.headers.get("x-real-ip") ?? "unknown";
    const ipHash = crypto.createHash("sha256").update(ip).digest("hex").slice(0, 16);
    const userAgent = req.headers.get("user-agent") ?? null;
    const referer = req.headers.get("referer") ?? null;

    await prisma.clickEvent.create({
      data: {
        trackingLinkId: trackingLink.id,
        ipHash,
        userAgent,
        referer,
      },
    });

    await prisma.trackingLink.update({
      where: { id: trackingLink.id },
      data: { totalClicks: { increment: 1 } },
    });

    if (trackingLink.videoId) {
      await prisma.video.update({
        where: { id: trackingLink.videoId },
        data: { totalClicks: { increment: 1 } },
      });
    }

    return NextResponse.redirect(trackingLink.destinationUrl);
  } catch (error) {
    console.error("GET /api/tracking/click error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

