import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { calculateCreatorEarnings } from "@/lib/tracking";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { code, orderValue } = body;

    if (!code || orderValue == null) {
      return NextResponse.json(
        { error: "Missing required fields: code, orderValue" },
        { status: 400 }
      );
    }

    const trackingLink = await prisma.trackingLink.findUnique({
      where: { code },
      include: {
        campaign: { select: { revenueSharePct: true } },
      },
    });

    if (!trackingLink) {
      return NextResponse.json({ error: "Invalid tracking code" }, { status: 404 });
    }

    const commission = calculateCreatorEarnings(orderValue, trackingLink.campaign.revenueSharePct);

    const conversionEvent = await prisma.conversionEvent.create({
      data: {
        trackingLinkId: trackingLink.id,
        orderValue,
        commission,
      },
    });

    await prisma.trackingLink.update({
      where: { id: trackingLink.id },
      data: {
        totalConversions: { increment: 1 },
        totalRevenue: { increment: commission },
      },
    });

    if (trackingLink.videoId) {
      await prisma.video.update({
        where: { id: trackingLink.videoId },
        data: {
          totalConversions: { increment: 1 },
          totalEarnings: { increment: commission },
        },
      });
    }

    await prisma.creatorProfile.update({
      where: { id: trackingLink.creatorProfileId },
      data: {
        totalEarnings: { increment: commission },
      },
    });

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (trackingLink.videoId) {
      await prisma.earningsRecord.upsert({
        where: {
          videoId_date: {
            videoId: trackingLink.videoId,
            date: today,
          },
        },
        update: {
          conversions: { increment: 1 },
          revenue: { increment: orderValue },
          earnings: { increment: commission },
        },
        create: {
          videoId: trackingLink.videoId,
          date: today,
          conversions: 1,
          revenue: orderValue,
          earnings: commission,
        },
      });
    }

    return NextResponse.json({
      success: true,
      conversionId: conversionEvent.id,
      commission,
    });
  } catch (error) {
    console.error("POST /api/tracking/convert error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

