import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/auth";
import { prisma } from "@/lib/prisma";
import { generateTrackingCode } from "@/lib/tracking";

export async function GET() {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const user = session.user as any;

    const creatorProfile = await prisma.creatorProfile.findUnique({
      where: { userId: user.id },
    });

    if (!creatorProfile) {
      return NextResponse.json({ error: "Creator profile not found" }, { status: 404 });
    }

    const links = await prisma.trackingLink.findMany({
      where: { creatorProfileId: creatorProfile.id },
      include: {
        campaign: { select: { id: true, title: true } },
        video: { select: { id: true, title: true } },
      },
      orderBy: { createdAt: "desc" },
    });

    return NextResponse.json(links);
  } catch (error) {
    console.error("GET /api/links error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

export async function POST(req: NextRequest) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const user = session.user as any;

    const creatorProfile = await prisma.creatorProfile.findUnique({
      where: { userId: user.id },
    });

    if (!creatorProfile) {
      return NextResponse.json({ error: "Creator profile not found" }, { status: 404 });
    }

    const body = await req.json();
    const { campaignId, videoId, destinationUrl } = body;

    if (!campaignId || !destinationUrl) {
      return NextResponse.json(
        { error: "campaignId and destinationUrl are required" },
        { status: 400 }
      );
    }

    const campaign = await prisma.campaign.findUnique({
      where: { id: campaignId },
    });
    if (!campaign) {
      return NextResponse.json({ error: "Campaign not found" }, { status: 404 });
    }

    if (videoId) {
      const video = await prisma.video.findUnique({ where: { id: videoId } });
      if (!video || video.creatorProfileId !== creatorProfile.id) {
        return NextResponse.json({ error: "Video not found or not owned by you" }, { status: 404 });
      }
    }

    const code = generateTrackingCode();

    const link = await prisma.trackingLink.create({
      data: {
        creatorProfileId: creatorProfile.id,
        campaignId,
        videoId: videoId ?? null,
        code,
        destinationUrl,
      },
    });

    return NextResponse.json(link, { status: 201 });
  } catch (error) {
    console.error("POST /api/links error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

