import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/auth";
import { prisma } from "@/lib/prisma";
import { generateTrackingCode } from "@/lib/tracking";

export async function PUT(
  req: NextRequest,
  { params }: { params: Promise<{ campaignId: string; applicationId: string }> }
) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const user = session.user as any;
    const { campaignId, applicationId } = await params;

    const campaign = await prisma.campaign.findUnique({
      where: { id: campaignId },
      include: { brandProfile: true },
    });

    if (!campaign) {
      return NextResponse.json({ error: "Campaign not found" }, { status: 404 });
    }

    if (campaign.brandProfile.userId !== user.id) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const application = await prisma.campaignApplication.findUnique({
      where: { id: applicationId },
    });

    if (!application || application.campaignId !== campaignId) {
      return NextResponse.json({ error: "Application not found" }, { status: 404 });
    }

    const body = await req.json();
    const { status } = body;

    if (!status || !["APPROVED", "REJECTED"].includes(status)) {
      return NextResponse.json(
        { error: "Status must be APPROVED or REJECTED" },
        { status: 400 }
      );
    }

    const updated = await prisma.campaignApplication.update({
      where: { id: applicationId },
      data: { status },
    });

    let trackingLink = null;

    if (status === "APPROVED") {
      const code = generateTrackingCode();
      const destinationUrl = campaign.brandProfile.website
        ? campaign.brandProfile.website
        : `${process.env.NEXT_PUBLIC_APP_URL ?? ""}/campaigns/${campaignId}`;

      trackingLink = await prisma.trackingLink.create({
        data: {
          creatorProfileId: application.creatorProfileId,
          campaignId,
          code,
          destinationUrl,
        },
      });
    }

    return NextResponse.json({ application: updated, trackingLink });
  } catch (error) {
    console.error("PUT /api/campaigns/[campaignId]/applications/[applicationId] error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

