import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/auth";
import { prisma } from "@/lib/prisma";

export async function GET() {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const user = session.user as any;

    const creatorProfile = await prisma.creatorProfile.findUnique({
      where: { userId: user.id },
    });

    if (!creatorProfile) {
      return NextResponse.json({ error: "Creator profile not found" }, { status: 404 });
    }

    const videos = await prisma.video.findMany({
      where: { creatorProfileId: creatorProfile.id },
      include: {
        campaign: { select: { id: true, title: true, niche: true } },
        _count: { select: { earningsRecords: true, trackingLinks: true } },
      },
      orderBy: { createdAt: "desc" },
    });

    const totalEarnings = videos.reduce((sum, v) => sum + v.totalEarnings, 0);
    const totalViews = videos.reduce((sum, v) => sum + v.totalViews, 0);
    const totalClicks = videos.reduce((sum, v) => sum + v.totalClicks, 0);

    return NextResponse.json({
      videos,
      totals: { totalEarnings, totalViews, totalClicks, videoCount: videos.length },
    });
  } catch (error) {
    console.error("GET /api/videos error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

export async function POST(req: NextRequest) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const user = session.user as any;

    const creatorProfile = await prisma.creatorProfile.findUnique({
      where: { userId: user.id },
    });

    if (!creatorProfile) {
      return NextResponse.json({ error: "Creator profile not found" }, { status: 404 });
    }

    const body = await req.json();
    const { title, platform, externalUrl, campaignId } = body;

    if (!title || !platform) {
      return NextResponse.json({ error: "Title and platform are required" }, { status: 400 });
    }

    if (campaignId) {
      const campaign = await prisma.campaign.findUnique({
        where: { id: campaignId },
      });
      if (!campaign) {
        return NextResponse.json({ error: "Campaign not found" }, { status: 404 });
      }
    }

    const video = await prisma.video.create({
      data: {
        creatorProfileId: creatorProfile.id,
        title,
        platform,
        externalUrl: externalUrl ?? null,
        campaignId: campaignId ?? null,
        publishedAt: new Date(),
      },
    });

    return NextResponse.json(video, { status: 201 });
  } catch (error) {
    console.error("POST /api/videos error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

