import crypto from "crypto";

type TrackingTokenPayload = {
  jti: string;
  clickEventId: string;
  trackingLinkId: string;
  code: string;
  campaignId: string;
  videoId: string | null;
  iat: number;
  exp: number;
};

type TrackingTokenResult =
  | { valid: true; payload: TrackingTokenPayload }
  | { valid: false; reason: string };

function toBase64Url(value: string): string {
  return Buffer.from(value).toString("base64url");
}

function fromBase64Url(value: string): string {
  return Buffer.from(value, "base64url").toString("utf8");
}

function getTrackingSigningSecret(): string {
  return process.env.TRACKING_SIGNING_SECRET ?? process.env.NEXTAUTH_SECRET ?? "local-dev-secret";
}

function sign(input: string): string {
  return crypto
    .createHmac("sha256", getTrackingSigningSecret())
    .update(input)
    .digest("base64url");
}

export function getTrackingTokenTtlSeconds(): number {
  const configured = Number(process.env.TRACKING_TOKEN_TTL_SECONDS ?? 60 * 60 * 24 * 7);
  return Number.isFinite(configured) && configured > 0 ? Math.floor(configured) : 60 * 60 * 24 * 7;
}

export function createTrackingToken(payload: TrackingTokenPayload): string {
  const header = {
    alg: "HS256",
    typ: "JWT",
  };

  const encodedHeader = toBase64Url(JSON.stringify(header));
  const encodedPayload = toBase64Url(JSON.stringify(payload));
  const signature = sign(`${encodedHeader}.${encodedPayload}`);
  return `${encodedHeader}.${encodedPayload}.${signature}`;
}

export function verifyTrackingToken(token: string): TrackingTokenResult {
  const segments = token.split(".");
  if (segments.length !== 3) {
    return { valid: false, reason: "Malformed token" };
  }

  const [encodedHeader, encodedPayload, signature] = segments;
  const expected = sign(`${encodedHeader}.${encodedPayload}`);
  const signatureBytes = Buffer.from(signature);
  const expectedBytes = Buffer.from(expected);
  if (signatureBytes.length !== expectedBytes.length) {
    return { valid: false, reason: "Invalid signature" };
  }

  if (!crypto.timingSafeEqual(signatureBytes, expectedBytes)) {
    return { valid: false, reason: "Invalid signature" };
  }

  try {
    const payload = JSON.parse(fromBase64Url(encodedPayload)) as TrackingTokenPayload;
    const now = Math.floor(Date.now() / 1000);
    if (!payload?.exp || payload.exp < now) {
      return { valid: false, reason: "Token expired" };
    }

    if (
      !payload.jti ||
      !payload.clickEventId ||
      !payload.trackingLinkId ||
      !payload.code ||
      !payload.campaignId
    ) {
      return { valid: false, reason: "Invalid payload" };
    }

    return { valid: true, payload };
  } catch {
    return { valid: false, reason: "Invalid payload" };
  }
}

